<div class="wrap">
  <h1>Sketch Budget</h1>
  <p class="hint">Log your monthly income and spending by category. A hand-drawn bar chart shows where your money goes.</p>

  <section class="card" aria-labelledby="income-h">
    <h2 id="income-h">Monthly income</h2>
    <div class="grid grid-2">
      <div>
        <label for="currency">Currency symbol</label>
        <input type="text" id="currency" maxlength="3" inputmode="text" autocomplete="off" value="$">
      </div>
      <div>
        <label for="income">Income this month</label>
        <input type="number" id="income" min="0" step="any" inputmode="decimal" placeholder="0">
      </div>
    </div>
  </section>

  <section class="card" aria-labelledby="spend-h">
    <h2 id="spend-h">Spending by category</h2>
    <form id="add-form" class="row" autocomplete="off">
      <div>
        <label for="cat-name">Category</label>
        <input type="text" id="cat-name" placeholder="e.g. Groceries" autocomplete="off">
      </div>
      <div>
        <label for="cat-amt">Amount</label>
        <input type="number" id="cat-amt" min="0" step="any" inputmode="decimal" placeholder="0">
      </div>
      <div class="add-btn">
        <label class="sr-only" for="cat-add">Add category</label>
        <button type="submit" class="primary" id="cat-add">Add</button>
      </div>
    </form>
    <div id="spend-list" role="group" aria-label="Spending categories"></div>
    <div class="summary" id="summary"></div>
  </section>

  <section class="card" aria-labelledby="chart-h">
    <h2 id="chart-h">Where it goes</h2>
    <div id="chart-area"></div>
    <div class="toolbar">
      <button type="button" id="redraw">Redraw sketch</button>
      <span class="spacer"></span>
      <button type="button" id="clear">Clear all</button>
    </div>
    <p class="note">The chart is redrawn with fresh hand-drawn wobble each time.</p>
  </section>

  <p class="status" id="status" role="status" aria-live="polite"></p>
  <p class="foot">Your budget is saved on this device.</p>
</div>

<script>
(function () {
  var KEY = 'sketch-budget-v1';
  var store = (window.alfy && window.alfy.storage) ? window.alfy.storage : null;

  var PALETTE = ['#c15f3c', '#4a6b8a', '#6a8a4a', '#8a6a4a', '#8a4a6b', '#4a8a8a', '#8a8a4a', '#5a5a5a'];

  var state = { income: 0, currency: '$', categories: [] };
  var seed = 1;

  var el = {
    income: document.getElementById('income'),
    currency: document.getElementById('currency'),
    catName: document.getElementById('cat-name'),
    catAmt: document.getElementById('cat-amt'),
    form: document.getElementById('add-form'),
    list: document.getElementById('spend-list'),
    summary: document.getElementById('summary'),
    chart: document.getElementById('chart-area'),
    status: document.getElementById('status'),
    redraw: document.getElementById('redraw'),
    clear: document.getElementById('clear')
  };

  function rand() {
    seed = (seed * 1664525 + 1013904223) % 4294967296;
    return seed / 4294967296;
  }

  function fmt(n) {
    var v = Number(n) || 0;
    return (state.currency || '$') + v.toLocaleString(undefined, { maximumFractionDigits: 2 });
  }

  function status(msg, isErr) {
    el.status.textContent = msg || '';
    el.status.className = 'status' + (isErr ? ' err' : '');
  }

  function save() {
    if (store) store.set(KEY, state);
  }

  function sketchPath(x1, y1, x2, y2) {
    var dx = x2 - x1, dy = y2 - y1;
    var len = Math.sqrt(dx * dx + dy * dy) || 1;
    var steps = Math.max(3, Math.min(14, Math.round(len / 24)));
    var amp = Math.min(3, len * 0.02);
    var px = -dy / len, py = dx / len;
    var pts = [];
    for (var i = 0; i <= steps; i++) {
      var t = i / steps;
      var off = (i === 0 || i === steps) ? 0 : (rand() - 0.5) * 2 * amp;
      pts.push([x1 + dx * t + px * off, y1 + dy * t + py * off]);
    }
    var d = 'M ' + pts[0][0].toFixed(1) + ' ' + pts[0][1].toFixed(1);
    for (var j = 1; j < pts.length; j++) d += ' L ' + pts[j][0].toFixed(1) + ' ' + pts[j][1].toFixed(1);
    return d;
  }

  function sketchRect(x, y, w, h) {
    return [
      sketchPath(x, y, x + w, y),
      sketchPath(x + w, y, x + w, y + h),
      sketchPath(x + w, y + h, x, y + h),
      sketchPath(x, y + h, x, y)
    ].join(' ');
  }

  function buildChart(items, maxVal) {
    var W = 680, labelW = 132, padR = 78, padT = 18, padB = 26;
    var barH = 40, gap = 22;
    var plotX = labelW, plotW = W - labelW - padR;
    var H = padT + items.length * (barH + gap) - gap + padB;
    var baseY = padT + items.length * (barH + gap) - gap + 4;
    var svg = '<svg class="chart" viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Bar chart of spending by category">';

    svg += '<path d="' + sketchPath(plotX - 4, padT - 6, plotX - 4, baseY) + '" fill="none" stroke="var(--text-muted)" stroke-width="1.4" opacity="0.5"/>';
    svg += '<path d="' + sketchPath(plotX - 4, baseY, W - 8, baseY) + '" fill="none" stroke="var(--text-muted)" stroke-width="1.4" opacity="0.5"/>';

    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      var color = PALETTE[i % PALETTE.length];
      var y = padT + i * (barH + gap);
      var w = maxVal > 0 ? Math.max(2, (it.amount / maxVal) * plotW) : 2;
      var x = plotX;

      svg += '<path d="' + sketchRect(x, y, w, barH) + '" fill="' + color + '" fill-opacity="0.85" stroke="' + color + '" stroke-width="1.6" stroke-linejoin="round"/>';
      svg += '<path d="' + sketchPath(x + 4, y + 6, x + w - 4, y + 6) + '" fill="none" stroke="' + color + '" stroke-width="1" opacity="0.4"/>';

      var name = it.name.length > 15 ? it.name.slice(0, 14) + '…' : it.name;
      svg += '<text x="' + (plotX - 10) + '" y="' + (y + barH / 2 + 5) + '" text-anchor="end" font-size="13" fill="var(--text-primary)">' + esc(name) + '</text>';
      svg += '<text x="' + (x + w + 8) + '" y="' + (y + barH / 2 + 5) + '" text-anchor="start" font-size="13" fill="var(--text-muted)">' + esc(fmt(it.amount)) + '</text>';
    }
    svg += '</svg>';

    var legend = '<div class="legend">';
    for (var k = 0; k < items.length; k++) {
      legend += '<span><i style="background:' + PALETTE[k % PALETTE.length] + '"></i>' + esc(items[k].name) + '</span>';
    }
    legend += '</div>';
    return svg + legend;
  }

  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
    });
  }

  function renderList() {
    if (!state.categories.length) {
      el.list.innerHTML = '<div class="empty"><svg width="46" height="46" viewBox="0 0 46 46" fill="none" stroke="var(--text-muted)" stroke-width="2" stroke-linecap="round"><path d="M6 40 L20 18 L28 28 L40 8"/><path d="M30 8 L40 8 L40 18"/></svg><p>No categories yet. Add your first spending category above to see the chart.</p></div>';
    } else {
      var html = '';
      for (var i = 0; i < state.categories.length; i++) {
        var c = state.categories[i];
        html += '<div class="spend-row">'
          + '<input type="text" value="' + esc(c.name) + '" data-i="' + i + '" data-f="name" aria-label="Category name" autocomplete="off">'
          + '<input type="number" min="0" step="any" inputmode="decimal" value="' + c.amount + '" data-i="' + i + '" data-f="amount" aria-label="Amount for ' + esc(c.name) + '">'
          + '<button type="button" class="icon" data-del="' + i + '" aria-label="Remove ' + esc(c.name) + '">&times;</button>'
          + '</div>';
      }
      el.list.innerHTML = html;
    }
    renderSummary();
  }

  function renderSummary() {
    var spent = 0;
    for (var i = 0; i < state.categories.length; i++) spent += Number(state.categories[i].amount) || 0;
    var left = (Number(state.income) || 0) - spent;
    el.summary.innerHTML =
      '<div class="stat"><div class="k">Income</div><div class="v">' + esc(fmt(state.income)) + '</div></div>'
      + '<div class="stat"><div class="k">Spent</div><div class="v">' + esc(fmt(spent)) + '</div></div>'
      + '<div class="stat"><div class="k">Left over</div><div class="v' + (left < 0 ? '' : ' pos') + '">' + esc(fmt(left)) + '</div></div>';
  }

  function renderChart() {
    var items = [];
    for (var i = 0; i < state.categories.length; i++) {
      var a = Number(state.categories[i].amount) || 0;
      if (a > 0) items.push({ name: state.categories[i].name || 'Untitled', amount: a });
    }
    if (!items.length) {
      el.chart.innerHTML = '<div class="empty"><svg width="46" height="46" viewBox="0 0 46 46" fill="none" stroke="var(--text-muted)" stroke-width="2" stroke-linecap="round"><path d="M10 38 L10 24"/><path d="M23 38 L23 14"/><path d="M36 38 L36 30"/></svg><p>Nothing to chart yet. Add a category with an amount above 0.</p></div>';
      return;
    }
    items.sort(function (a, b) { return b.amount - a.amount; });
    var maxVal = 0;
    for (var j = 0; j < items.length; j++) maxVal = Math.max(maxVal, items[j].amount);
    el.chart.innerHTML = buildChart(items, maxVal);
  }

  function renderAll() {
    renderList();
    renderChart();
  }

  function commit() {
    save();
    renderAll();
  }

  // --- events ---
  el.income.addEventListener('input', function () {
    state.income = Number(el.income.value) || 0;
    commit();
  });

  el.currency.addEventListener('input', function () {
    state.currency = el.currency.value;
    commit();
  });

  el.form.addEventListener('submit', function (e) {
    e.preventDefault();
    var name = el.catName.value.trim();
    var amt = Number(el.catAmt.value);
    if (!name) { status('Give the category a name first.', true); el.catName.focus(); return; }
    if (!(amt > 0)) { status('Enter an amount greater than 0.', true); el.catAmt.focus(); return; }
    state.categories.push({ name: name, amount: amt });
    el.catName.value = '';
    el.catAmt.value = '';
    status('Added "' + name + '".');
    commit();
    el.catName.focus();
  });

  el.list.addEventListener('input', function (e) {
    var t = e.target;
    if (t.dataset.i === undefined || !t.dataset.f) return;
    var idx = Number(t.dataset.i);
    if (!state.categories[idx]) return;
    if (t.dataset.f === 'name') state.categories[idx].name = t.value;
    else state.categories[idx].amount = Number(t.value) || 0;
    save();
    renderSummary();
    renderChart();
  });

  el.list.addEventListener('click', function (e) {
    var t = e.target;
    if (t.dataset.del === undefined) return;
    var idx = Number(t.dataset.del);
    var removed = state.categories.splice(idx, 1)[0];
    status('Removed "' + (removed ? removed.name : '') + '".');
    commit();
  });

  el.redraw.addEventListener('click', function () {
    seed = (Date.now() % 1000000) + 7;
    renderChart();
    status('Redrawn with a fresh sketch.');
  });

  el.clear.addEventListener('click', function () {
    if (el.clear.dataset.confirm === '1') {
      state.income = 0;
      state.categories = [];
      el.income.value = '';
      el.clear.dataset.confirm = '';
      el.clear.textContent = 'Clear all';
      status('Budget cleared.');
      commit();
    } else {
      el.clear.dataset.confirm = '1';
      el.clear.textContent = 'Sure? Tap again';
      status('Tap "Sure?" again to clear everything.');
    }
  });

  // --- init ---
  function init() {
    if (store && store.get) {
      store.get(KEY).then(function (v) {
        if (v && typeof v === 'object') {
          state.income = Number(v.income) || 0;
          state.currency = typeof v.currency === 'string' ? v.currency : '$';
          if (Array.isArray(v.categories)) {
            state.categories = v.categories.map(function (c) {
              return { name: String(c.name || ''), amount: Number(c.amount) || 0 };
            });
          }
        }
        hydrate();
      }).catch(hydrate);
    } else {
      hydrate();
    }
  }

  function hydrate() {
    el.income.value = state.income || '';
    el.currency.value = state.currency;
    renderAll();
  }

  init();
})();
</script>
</body>
</html>
